  switch (hook) {
    case 'post.beforeRender':
      // HTML icerigini degistir ve geri dondur
      return args[0];

    case 'page.head':
      // <head> icine HTML ekle
      return args[0];

    case 'page.bodyEnd':
      // </body> oncesine HTML ekle
      return args[0];

    default:
      return args[0]; // degistirmeden gec
  }
